export function parseQueryParameters(query) {
    const result = Object.create(null);
    const source = query.startsWith('?') ? query.slice(1) : query;
    if (source === '')
        return result;
    const decode = text => {
        try {
            return decodeURIComponent(text.replace(/\+/g, ' '));
        }
        catch {
            throw new Error('Invalid encoding');
        }
    };
    for (const field of source.split('&')) {
        if (field === '')
            continue;
        const equals = field.indexOf('=');
        const key = decode(equals < 0 ? field : field.slice(0, equals));
        const value = decode(equals < 0 ? '' : field.slice(equals + 1));
        if (!Object.prototype.hasOwnProperty.call(result, key))
            result[key] = [];
        result[key].push(value);
    }
    return result;
}
